// =============================================================================
// apn-presets — suggested internet APNs for the SIM's home network
// =============================================================================
// Reads public/data/apn-presets.json (generated by `bun run apn:update` from
// LineageOS's APN database; see scripts-dev/build-apn-presets.ts). The file is
// fetched once on first use and cached for the page's lifetime.
//
// The SIM's home PLMN comes from its IMSI: 3 MCC digits, then a 2- or 3-digit
// MNC. Instead of a per-MCC length table, both readings are looked up in the
// data: a 3-digit match wins, since a 2-digit MNC's PLMN cannot also exist as
// that 3-digit prefix in the same MCC.
// =============================================================================

/** [label, apn] | [label, apn, pdp] | [label, apn, pdp | "", 1 (MVNO)] */
type PresetRow = [string, string, string?, 1?];

interface PresetFile {
  plmns: Record<string, PresetRow[]>;
}

export interface ApnPreset {
  /** Carrier's name for the entry, e.g. "SMART LTE". */
  label: string;
  /** The APN string. */
  apn: string;
  /** "ipv4" | "ipv6" | "ipv4v6" when the carrier states one, else null. */
  pdpType: string | null;
  /** A brand riding the host network (MVNO), not the network's own entry. */
  mvno: boolean;
}

export interface ApnPresetMatch {
  /** The PLMN the IMSI resolved to, e.g. "51503". */
  plmn: string;
  presets: ApnPreset[];
}

const PRESET_URL = "/data/apn-presets.json";

let filePromise: Promise<PresetFile> | null = null;

/** Loads the preset file once; a failed load is retried on the next call. */
export function loadApnPresets(): Promise<PresetFile> {
  if (!filePromise) {
    filePromise = fetch(PRESET_URL)
      .then((res) => {
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        return res.json() as Promise<PresetFile>;
      })
      .catch((err) => {
        filePromise = null;
        throw err;
      });
  }
  return filePromise;
}

/** The presets for an IMSI's home network, or null when the IMSI is unusable or the network is unknown. */
export function matchApnPresets(
  file: PresetFile,
  imsi: string | null | undefined,
): ApnPresetMatch | null {
  const digits = (imsi ?? "").trim();
  if (!/^\d{6,15}$/.test(digits)) return null;

  for (const plmn of [digits.slice(0, 6), digits.slice(0, 5)]) {
    const rows = file.plmns[plmn];
    if (rows?.length) {
      return {
        plmn,
        presets: rows.map(([label, apn, pdp, mvno]) => ({
          label,
          apn,
          pdpType: pdp || null,
          mvno: mvno === 1,
        })),
      };
    }
  }
  return null;
}
